S=/private/tmp/claude-501/-Users-merill--claude-spares-spare-pDZGhh/9bc9d96b-2b79-4851-80f9-ab9184d1fb1a/scratchpad; cd $S/zta-xlsx/x; python3 -I - <<'EOF'
import re, xml.etree.ElementTree as ET
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
ss=[ ''.join(t.text or '' for t in si.iter('{%s}t'%ns['m'])) for si in ET.parse('xl/sharedStrings.xml').getroot().findall('m:si',ns)]
def rows(sheet, n=12):
    root=ET.parse(f'xl/worksheets/{sheet}').getroot()
    out=[]
    for r in root.iter('{%s}row'%ns['m']):
        vals=[]
        for c in r.findall('m:c',ns):
            v=c.find('m:v',ns); t=c.get('t')
            if v is None:
                is_=c.find('m:is',ns)
                if is_ is not None: vals.append((c.get('r'),''.join(x.text or '' for x in is_.iter('{%s}t'%ns['m']))))
                continue
            val=ss[int(v.text)] if t=='s' else v.text
            vals.append((c.get('r'),val[:60]))
        if vals: out.append(vals)
        if len(out)>=n: break
    return out
for r in rows('sheet2.xml',8): print(r)
EOF

